use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::ffi::CString;
use std::os::raw::c_void;

extern "C" {
    fn malloc(size: usize) -> *mut c_void;
    fn free(ptr: *mut c_void);
}

#[derive(Clone)]
struct SessionCache {
    inner: Arc<Mutex<HashMap<String, *mut c_void>>>,
}

unsafe impl Send for SessionCache {}
unsafe impl Sync for SessionCache {}

impl SessionCache {
    fn new() -> Self {
        SessionCache {
            inner: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn store_session(&self, token: &str, data: &[u8]) -> Result<(), String> {
        unsafe {
            let ptr = malloc(data.len());
            if ptr.is_null() {
                return Err("allocation failed".to_string());
            }
            std::ptr::copy_nonoverlapping(data.as_ptr(), ptr as *mut u8, data.len());
            let mut cache = self.inner.lock().unwrap();
            cache.insert(token.to_string(), ptr);
        }
        Ok(())
    }

    fn invalidate_session(&self, token: &str) {
        let mut cache = self.inner.lock().unwrap();
        if let Some(ptr) = cache.remove(token) {
            unsafe { free(ptr); }
        }
    }

    // Called during credential rotation - invalidates all sessions
    fn rotate_credentials(&self) {
        let mut cache = self.inner.lock().unwrap();
        for (_token, ptr) in cache.iter() {
            unsafe { free(*ptr); }
        }
        // BUG: does not clear the map, leaving dangling pointers
        // Next call to invalidate_session will double-free
    }
}

async fn login(
    cache: web::Data<SessionCache>,
    req: HttpRequest,
) -> HttpResponse {
    let token = req.headers().get("Authorization")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("anonymous");

    let session_data = b"user_session_context_data_placeholder";
    match cache.store_session(token, session_data) {
        Ok(_) => HttpResponse::Ok().body("session created"),
        Err(e) => HttpResponse::InternalServerError().body(e),
    }
}

async fn logout(
    cache: web::Data<SessionCache>,
    req: HttpRequest,
) -> HttpResponse {
    let token = req.headers().get("Authorization")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("anonymous");

    cache.invalidate_session(token);
    HttpResponse::Ok().body("logged out")
}

async fn rotate(
    cache: web::Data<SessionCache>,
) -> HttpResponse {
    cache.rotate_credentials();
    HttpResponse::Ok().body("credentials rotated")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let cache = SessionCache::new();

    // Spawn rotation task every 60 seconds
    let rotation_cache = cache.clone();
    actix_web::rt::spawn(async move {
        loop {
            actix_web::rt::time::sleep(std::time::Duration::from_secs(60)).await;
            rotation_cache.rotate_credentials();
        }
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(cache.clone()))
            .route("/login", web::post().to(login))
            .route("/logout", web::post().to(logout))
            .route("/rotate", web::post().to(rotate))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
